-- Invoker functions retain report RLS. Scores describe received reports, not prevalence.
create function public.map_reports(west float8,south float8,east float8,north float8,category uuid default null,barangay uuid default null,report_state public.report_status default null,since timestamptz default null,until timestamptz default null,verified_only boolean default false,unresolved_only boolean default false,office uuid default null)
returns setof public.reports language sql stable security invoker set search_path='' as $$select r.* from public.reports r where extensions.st_intersects(r.location::extensions.geometry,extensions.st_makeenvelope(west,south,east,north,4326)) and (category is null or r.category_id=category) and (barangay is null or r.barangay_id=barangay) and (report_state is null or r.status=report_state) and (since is null or r.created_at>=since) and (until is null or r.created_at<until) and (not verified_only or r.verified_at is not null) and (not unresolved_only or r.status not in ('resolved','rejected','duplicate')) and (office is null or r.organization_id=office) and r.status not in ('rejected','duplicate') order by r.created_at desc limit 1000$$;
create function public.recurrence_candidates(p_id uuid) returns table(id uuid,title text,status public.report_status,distance_m float8,verified_at timestamptz) language sql stable security invoker set search_path='' as $$select b.id,b.title,b.status,extensions.st_distance(a.location,b.location),b.verified_at from public.reports a join public.reports b on a.category_id=b.category_id and a.id<>b.id cross join public.analytics_settings s where a.id=p_id and b.status not in ('rejected','duplicate') and abs(extract(epoch from a.created_at-b.created_at))<=s.window_days*86400 and extensions.st_dwithin(a.location,b.location,s.radius_m) order by 4 limit 50$$;
create function public.barangay_summary() returns table(id uuid,name text,submitted bigint,verified bigint,unresolved bigint,resolved bigint,oldest_days numeric,severity_total bigint,score numeric) language sql stable security invoker set search_path='' as $$select b.id,b.name,count(r.id),count(r.id) filter(where r.verified_at is not null and r.status not in ('rejected','duplicate')),count(r.id) filter(where r.verified_at is not null and r.status not in ('resolved','rejected','duplicate')),count(r.id) filter(where r.status='resolved'),coalesce(max(extract(epoch from now()-r.created_at)/86400) filter(where r.verified_at is not null and r.status not in ('resolved','rejected','duplicate')),0),coalesce(sum(r.severity) filter(where r.verified_at is not null and r.status not in ('resolved','rejected','duplicate')),0),count(r.id) filter(where r.verified_at is not null and r.status not in ('resolved','rejected','duplicate'))*s.count_weight+coalesce(sum(r.severity) filter(where r.verified_at is not null and r.status not in ('resolved','rejected','duplicate')),0)*s.severity_weight+coalesce(max(extract(epoch from now()-r.created_at)/86400) filter(where r.verified_at is not null and r.status not in ('resolved','rejected','duplicate')),0)*s.age_weight from public.barangays b cross join public.analytics_settings s left join public.reports r on r.barangay_id=b.id group by b.id,b.name,s.count_weight,s.severity_weight,s.age_weight order by 9 desc$$;
create function public.dashboard_counts() returns jsonb language sql stable security invoker set search_path='' as $$select jsonb_build_object('total',count(*),'review',count(*) filter(where status in ('submitted','under_review')),'verified',count(*) filter(where verified_at is not null and status not in ('duplicate','rejected')),'progress',count(*) filter(where status='in_progress'),'resolved',count(*) filter(where status='resolved'),'unresolved',count(*) filter(where status not in ('resolved','rejected','duplicate'))) from public.reports$$;
revoke execute on function public.map_reports,public.recurrence_candidates,public.barangay_summary,public.dashboard_counts from public,anon;
grant execute on function public.map_reports,public.recurrence_candidates,public.barangay_summary,public.dashboard_counts to authenticated;
